export class OrderedMultiDict {
  constructor() {
    this.entryList = [];
    this.keyOrder = [];
    this.valuesByKey = new Map();
  }

  add(key, value) {
    if (!this.valuesByKey.has(key)) {
      this.valuesByKey.set(key, []);
      this.keyOrder.push(key);
    }

    this.valuesByKey.get(key).push(value);
    this.entryList.push([key, value]);
  }

  getlist(key) {
    const values = this.valuesByKey.get(key);
    return values ? [...values] : [];
  }

  keys() {
    return [...this.keyOrder];
  }

  items() {
    return this.keyOrder.map((key) => {
      const values = this.valuesByKey.get(key);
      return tuple(key, values[values.length - 1]);
    });
  }

  toPythonRepr() {
    const allPairs = this.entryList.map(([key, value]) => tuple(key, value));
    return `OrderedMultiDict(${toPythonRepr(allPairs)})`;
  }

  toString() {
    return this.toPythonRepr();
  }
}

