export class PythonTuple {
  constructor(items) {
    this.items = [...items];
  }

  toPythonRepr() {
    if (this.items.length === 1) {
      return `(${toPythonRepr(this.items[0])},)`;
    }

    return `(${this.items.map((item) => toPythonRepr(item)).join(', ')})`;
  }
}

export function tuple(...items) {
  return new PythonTuple(items);
}

export function toPythonRepr(value) {
  if (value && typeof value.toPythonRepr === 'function') {
    return value.toPythonRepr();
  }

  if (Array.isArray(value)) {
    return `[${value.map((item) => toPythonRepr(item)).join(', ')}]`;
  }

  if (typeof value === 'string') {
    return formatPythonString(value);
  }

  if (typeof value === 'boolean') {
    return value ? 'True' : 'False';
  }

  if (value === null || value === undefined) {
    return 'None';
  }

  return String(value);
}

function formatPythonString(value) {
  const quote = value.includes("'") && !value.includes('"') ? '"' : "'";
  let result = quote;

  for (const char of value) {
    const codePoint = char.codePointAt(0);

    if (char === '\\') {
      result += '\\\\';
      continue;
    }

    if (char === quote) {
      result += `\\${quote}`;
      continue;
    }

    if (char === '\t') {
      result += '\\t';
      continue;
    }

    if (char === '\n') {
      result += '\\n';
      continue;
    }

    if (char === '\r') {
      result += '\\r';
      continue;
    }

    if ((codePoint >= 0x00 && codePoint <= 0x1f) || (codePoint >= 0x7f && codePoint <= 0x9f)) {
      result += `\\x${codePoint.toString(16).padStart(2, '0')}`;
      continue;
    }

    result += char;
  }

  result += quote;
  return result;
}

